import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0005 — Content Security Policy nel webview (SPIKE-05)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0005-webview-csp.md","filePath":"adr/0005-webview-csp.md"}'),n={name:"adr/0005-webview-csp.md"};function r(s,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0005-—-content-security-policy-nel-webview-spike-05" tabindex="-1">ADR-0005 — Content Security Policy nel webview (SPIKE-05) <a class="header-anchor" href="#adr-0005-—-content-security-policy-nel-webview-spike-05" aria-label="Permalink to &quot;ADR-0005 — Content Security Policy nel webview (SPIKE-05)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (verifica manuale CodeMirror/KaTeX/Mermaid sotto CSP in M1)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-23</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.7 (CSP restrittiva, niente <code>unsafe-eval</code>), D-01</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><blockquote><p><strong>Nota (ADR-0051, accettata il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8).</strong> Il tag di build <code>production</code> non lo imposta più <code>wails build</code>: lo passa <code>go build -tags production</code> (<code>scripts/build-desktop-bin.sh</code>, più <code>gtk3</code> su Linux). Le due CSP e la regola per sviluppo e produzione restano quelle descritte. Il testo qui sotto è storico e non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il frontend è servito dall&#39;asset server di Wails; in sviluppo passa dal dev server Vite (HMR via WebSocket, stili inline). Serve una CSP stretta in produzione senza rompere lo sviluppo.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p>Due costanti <code>app.ContentSecurityPolicy</code> selezionate dal build tag <code>production</code> (che <code>wails build</code> imposta):</p><ul><li><strong>Produzione</strong> (<code>csp_prod.go</code>): <code>default-src &#39;self&#39;; script-src &#39;self&#39; &#39;wasm-unsafe-eval&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: blob:; connect-src &#39;self&#39;; frame-src &#39;none&#39;; object-src &#39;none&#39;; base-uri &#39;none&#39;; form-action &#39;none&#39;</code>. Niente <code>unsafe-eval</code>; <code>wasm-unsafe-eval</code> serve all&#39;Argon2id WASM (M2); <code>style-src &#39;unsafe-inline&#39;</code> è richiesto dagli stili calcolati di CodeMirror/KaTeX — non è CSS dell&#39;utente (D-01: nessun CSS personalizzato viene mai caricato).</li><li><strong>Sviluppo</strong> (<code>csp_dev.go</code>): aggiunge <code>unsafe-inline</code>/<code>unsafe-eval</code> per gli script e <code>ws://localhost:*</code> per HMR.</li></ul><p>Gli header sono applicati dal middleware <code>cspMiddleware</code> in <code>main.go</code> (anche <code>X-Content-Type-Options: nosniff</code>, <code>Referrer-Policy: no-referrer</code>). Le chiamate al cloud non passano dal webview (vanno dal backend Go), quindi <code>connect-src &#39;self&#39;</code> basta.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Nonce per gli stili</strong> — scartata: CodeMirror e KaTeX impostano <code>style</code> dinamicamente; i nonce non coprono gli attributi di stile.</li><li><strong>CSP via <code>&lt;meta&gt;</code></strong> — scartata: l&#39;header dell&#39;asset server copre tutte le risorse e non dipende dall&#39;HTML.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Mermaid in M1 va eseguito con <code>securityLevel: &#39;strict&#39;</code> e senza <code>unsafe-eval</code>; se un elemento di rendering richiedesse <code>eval</code>, la risposta è isolarlo in un worker, non allargare la CSP.</p>',13)])])}const v=o(n,[["render",r]]);export{g as __pageData,v as default};
